    ('sandstone-nehru-jacket', 'sandstone-nehru-jacket', 'Textured Nehru Waistcoat & Kurta Set', 'FF-SANDSTON-001', 'Artisanal woven Nehru jacket layered over an ivory base. Designed for sangeets, poojas, and celebrat...', 'Artisanal woven Nehru jacket layered over an ivory base. Designed for sangeets, poojas, and celebratory evening dinners.', ARRAY['Textured Jacquard & Pure Linen weave', 'Chest pocket with integrated pocket square', 'Full satin interior lining for breathability'], 2299.00, 2999.00, 1034.00, 18.00, 'shirts', 'Shirts', 'Funky Fox', ARRAY['shirts', 'streetwear', 'menswear'], '/images/products/ethnic-nehru-jacket.webp', ARRAY['/images/products/ethnic-nehru-jacket.webp', '/images/products/ethnic-bandhgala-rust.webp'], 'Indian male model wearing a textured Nehru waistcoat in champagne gold over ivory kurta', 'active', true, false, 0, 64, 5, false),
    ('sage-olive-linen-kurta', 'sage-olive-linen-kurta', 'Minimalist Sage Linen Kurta Shirt', 'FF-SAGEOLIV-002', 'Effortless fusion of casual shirt and festive kurta. Roll the sleeves up for weekend gatherings or p...', 'Effortless fusion of casual shirt and festive kurta. Roll the sleeves up for weekend gatherings or pair with trousers for cultural occasions.', ARRAY['100% Breathable Organic European Linen', 'Roll-tab sleeves with horn button fastenings', 'Garment washed for ultra-soft lived-in texture'], 1499.00, 1999.00, 674.00, 18.00, 'shirts', 'Shirts', 'Funky Fox', ARRAY['shirts', 'streetwear', 'menswear'], '/images/products/ethnic-linen-kurta.webp', ARRAY['/images/products/ethnic-linen-kurta.webp', '/images/products/ethnic-asymmetric-kurta.webp'], 'Indian male model wearing a relaxed linen kurta shirt in muted olive sage', 'active', false, true, 0, 96, 5, false),
